                    companyName?: string | null;
                    /** @example AI-native content workflows for software teams. */
                    companyDescription?: string | null;
                    /**
                     * @description Set a preset tone profile. When provided without customTone, any saved custom tone is cleared.
                     * @example Professional
                     * @enum {string|null}
                     */
                    toneProfile?: "Conversational" | "Professional" | "Casual" | "Formal" | null;
                    /**
                     * @description Provide a custom tone override. Send an empty string or null to clear it.
                     * @example Clear, direct, and technically confident
                     */
                    customTone?: string | null;
